// mini_parity.rs — structural parity oracle for the mini-notation parser.
//
// `mini_golden.json` holds, for each pattern, the haps Strudel's real parser
// (@strudel/mini) produces over cycles 0..3 plus the pattern's `_steps`,
// generated by `tools/oracle/gen_mini_oracle.mjs`. Each pattern is re-parsed
// with rudel-mini, queried over the same window, and compared hap-for-hap
// (order-independent) on timespans, values, and step count, one test per
// pattern.
// SPDX-License-Identifier: AGPL-3.0-or-later

mod common;
use common::{canon_locs, golden_locs, golden_rows, rudel_rows};
use libtest_mimic::{Arguments, Failed, Trial};
use serde_json::{Value, value::RawValue};
use std::collections::BTreeMap;

const CYCLES: i64 = 3;

// nextest starts this binary once per test, and every start runs `main`, so
// it reads only what names the tests; each test parses the case it runs.
fn main() {
    let golden: BTreeMap<String, &'static RawValue> =
        serde_json::from_str(include_str!("../../../tools/oracle/mini_golden.json"))
            .expect("parse golden json");
    let trials = golden
        .into_iter()
        .map(|(code, entry)| {
            // Quoted: a pattern such as `-3 -x` would otherwise reach the
            // harness's argument parser as flags when nextest runs it by name.
            let name = format!("{code:?}");
            Trial::test(name, move || {
                let entry = serde_json::from_str(entry.get()).expect("entry");
                mini_notation_matches_strudel(&code, &entry)
            })
        })
        .collect();
    libtest_mimic::run(&Arguments::from_args(), trials).exit();
}

fn mini_notation_matches_strudel(code: &str, entry: &Value) -> Result<(), Failed> {
    let mut failures = Vec::new();
    let want = golden_rows(entry["haps"].as_array().expect("haps array"), true);
    let want_steps = match &entry["steps"] {
        Value::String(s) => s.clone(),
        _ => "_".to_string(),
    };
    let pat = rudel_mini::parse(code).map_err(|e| format!("rudel parse {code:?}: {e:?}"))?;
    let got = rudel_rows(&pat, CYCLES, true);
    if got != want {
        failures.push(format!(
            "strudel ({} haps): {:#?}\nrudel   ({} haps): {:#?}",
            want.len(),
            want,
            got.len(),
            got
        ));
    }
    let got_steps = match pat.steps {
        Some(s) => format!("{}/{}", s.numer(), s.denom()),
        None => "_".to_string(),
    };
    if got_steps != want_steps {
        failures.push(format!("steps: strudel {want_steps}, rudel {got_steps}"));
    }
    let want_locs = canon_locs(golden_locs(&entry["locs"]));
    let got_locs = canon_locs(rudel_mini::leaf_locations(code).expect("leaf locations"));
    if got_locs != want_locs {
        failures.push(format!(
            "leaf locations: strudel [{want_locs}], rudel [{got_locs}]"
        ));
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("\n\n").into())
    }
}
